}

// The rows tasteBlock reads: latest 6 likes + latest 6 dislikes, newest first,
// as JSON text. A scalar subquery, so it drops into any SELECT or RETURNING.
const TASTE_SQL = "(select coalesce(json_agg(t order by t.updated_at desc), '[]')::text from (" +
  "(select fb.vote, fb.updated_at, f.title, left(f.summary, 160) as summary from feedback fb join feed_items f on f.id = fb.feed_item_id where fb.vote = 1 order by fb.updated_at desc limit 6) " +
  "union all " +
  "(select fb.vote, fb.updated_at, f.title, left(f.summary, 160) as summary from feedback fb join feed_items f on f.id = fb.feed_item_id where fb.vote = -1 order by fb.updated_at desc limit 6)) t)";

const p = $('Prep feedback').first().json;
const s = $input.first().json || {};
const saved = Number(s.feed_item_id) > 0;
const mark = saved ? (Number(s.vote) === 1 ? '\u{1F44D}' : '\u{1F44E}') : '';
const title = String(s.title || '').slice(0, 80);
return [{ json: {
  answer: { callback_query_id: p.callback_id, text: saved ? mark + ' saved: ' + title : 'Could not save that — the item may be gone.' },
  edit: p.markup && saved ? { chat_id: p.chat_id, message_id: p.message_id, reply_markup: votedKeyboard(p.markup, p.id, Number(s.vote)) } : null,
  saved, title } }];

const r = $input.first().json;
const n = Number(r.backlog_total) || 0;
const on = String(r.value) === 'true';
let text;
if (on && n === 0) text = "Nothing to fix — every saved page already has a summary.";
else if (on) text = "On it. Working through " + n + " page" + (n === 1 ? '' : 's') +
  ", about " + Math.max(1, Math.round(n * 20 / 60)) + " min while your PC stays on. Say \"stop feed\" to stop.";
else text = "Stopped. I'll leave it alone — say \"fix feed\" whenever you want.";
let chat_id = __TG_CHAT__;
try { chat_id = $('Record update').first().json.chat_id || chat_id; } catch (e) {
  try { chat_id = $('Test normalize').first().json.chat_id || chat_id; } catch (e2) {}
}
return [{ json: { chat_id, output: text } }];

const ctx = $('Agent context').first().json;
const sources = ctx.sources || 'none', runs = ctx.runs || 'unknown', fix_check = ctx.fix_check || '', fix_web = ctx.fix_web || '', fix_synth = ctx.fix_synth || 'off', fix_verify = ctx.fix_verify || 'false', fix_recall = ctx.fix_recall || 'true', fix_fit = ctx.fix_fit || 'true';
return $('Feed switch?').all(1).map(i => ({ json: { ...i.json, sources, runs, fix_check, fix_web, fix_synth, fix_verify, fix_recall, fix_fit } }));

// #13 (2026-10-12): one cited answer across several feed items, instead of a list.
// "what's happening with AI policy in South Asia?" -> 3-6 sentences, every claim
// cited [n] against the numbered items WF-31 returned, then the numbered list
// (with 👍/👎) underneath. Wasim's calls: thinking off vs on built behind the
// switch fix_synth (off | fast | think) and measured; 1-2 items -> a short
// answer that says the feed is thin, no web; the source list stays.
//
// The route is decided here, in code: the 9B picks tools unreliably with
// thinking off (it answered 4/4 source-quality phrasings from context, #9).
// Inlined into WF-00 (route) and WF-45 synth_answer (everything else).
// Needs figures/norm/unsupportedFacts from answer-check.js inlined first.

// ---- which questions get a written answer ----

const BIG_PICTURE = new RegExp([
  "\\bwhat('?s| is| are)\\s+(happening|going on|changing|new)\\s+(with|in|on|around|for|across)\\b",
  "\\bwhat('?s| is) the (state|status|latest|story|picture|situation) (of|on|with|in)\\b",
  "\\bhow (are|is|do|does|have|has)\\b[^?]{0,60}\\b(handling|dealing|approaching|responding|reacting|adapting|coping|managing|tackling|using|adopting|regulating|treating|thinking about)\\b",
  "\\b(overview|summary|summari[sz]e|big picture|landscape|trends?|themes?|takeaways?|gist|state of play)\\b",
  "\\b(compare|comparison|versus|vs\\.?)\\b",
  "\\bwhat (do|does) (my|the) (feed|items|articles|sources) say about\\b",
  "\\bwhat are the (main|key|latest|big|major) (developments|debates|arguments|issues|questions|risks|players|moves)\\b",
  "\\b(explain|walk me through) (what|how|why)\\b",
].join('|'), 'i');

// Lists, follow-ups, commands and questions about the bot itself stay on the agent.
const NOT_SYNTH = new RegExp([
  'https?://',
  '#\\s?\\d+\\b',
  '\\b(first|second|third|fourth|fifth|last) (one|item|article|story|link)\\b',
  '\\b(item|number|no\\.?)\\s?\\d+\\b',
  '^\\s*(anything|any (news|updates?|items?))\\b',
  '\\b(show me|list|give me (a list|the list))\\b',
  '\\b(search|sweep|run|discover|find new|look up|scrape|add|remove|follow|unfollow|subscribe|schedule|transcribe)\\b',
  '\\b(run|runs|status|broke|broken|failed)\\b',
  '\\b(my|the|your) (sources?|feeds?)\\b(?! say)',
].join('|'), 'i');

function bigPictureQ(question) {
  const q = String(question || '').trim();
  if (!q || q.split(/\s+/).length < 3) return false;
  if (NOT_SYNTH.test(q)) return false;
  return BIG_PICTURE.test(q);
}

// ---- the prompt ----

const SYNTH_MAX_ITEMS = 8;
const EV_FULL = 1500;   // the first 3 items carry whole passages
const EV_SHORT = 600;

function evidenceText(ev) {
  if (!ev) return '';
  if (typeof ev === 'string') return ev;
  if (Array.isArray(ev)) return ev.map(evidenceText).filter(Boolean).join(' … ');
  if (typeof ev === 'object') return String(ev.text || ev.fragments || ev.headline || '');
  return '';
}

function itemTitle(it) {
  const t = String(it.title || '').trim();
  if (t && t !== 'null') return t;
  const m = String(it.canonical_url || '').match(/^https?:\/\/(?:www\.)?([^/]+)/i);
  return m ? m[1] : 'untitled';
}

function itemBlock(it, i) {
  const date = it.published_at ? String(it.published_at).slice(0, 10) : 'undated';
  const ev = evidenceText(it.evidence).replace(/\s+/g, ' ').trim().slice(0, i < 3 ? EV_FULL : EV_SHORT);
  return '[' + it.n + '] ' + itemTitle(it) + ' (published ' + date + ')\n' +
    'Summary: ' + String(it.summary || '').replace(/\s+/g, ' ').trim() + (ev ? '\nFrom the article: ' + ev : '');
}

const SYNTH_SYSTEM = 'You answer a question from the user\'s own research feed. Use ONLY the numbered items below. ' +
  'Write 3 to 6 sentences that pull the items together: what is happening, who is doing it, the figures and dates. ' +
  'End EVERY sentence with the number of each item it rests on, like [2] or [1][4]. Use only the numbers given. ' +
  'Quote figures and names exactly as the items give them. If items disagree, say so. ' +
  'Skip items that are off the question, and say what the items report, never what kind of page they are. ' +
  'If the question compares several things and the items cover only some, say plainly which ones the feed has nothing on. ' +
  'If none of the items answers the question, reply with exactly: ' + 'NOT IN FEED' + ' ' +
  'Plain text for Telegram: no markdown, no headings, no bullet list, no list of sources at the end.';

// The 9B's marker for "the items do not answer this" (measured 2026-10-12: asked
// to "say so", it wrote three sentences about an unrelated item instead).
const NOT_IN_FEED = /^\W*not in feed\W*$/i;
const NOTHING_REPLY = 'Your feed has nothing on this yet.';

function synthBody(model, question, items, mode, feedback) {
  const list = (items || []).slice(0, SYNTH_MAX_ITEMS).map(itemBlock).join('\n\n');
  const messages = [
    { role: 'system', content: SYNTH_SYSTEM },
    { role: 'user', content: 'Question: ' + question + '\n\nItems:\n' + list }];
  if (feedback) {
    messages.push({ role: 'assistant', content: feedback.previous });
    messages.push({ role: 'user', content: 'That answer broke the rules: ' + feedback.problems.join('; ') +
      '. Rewrite it. Every sentence must end with item numbers from the list, and every figure must come from the items you cite.' });
  }
  const think = mode === 'think';
  return { model, temperature: 0, messages,
    reasoning_effort: think ? 'medium' : 'none',
    max_tokens: think ? 6000 : 900 };
}

// ---- checking the answer ----

// "[1][4]", "[1, 4]" and "[1-3]" all count.
function citations(text) {
  const out = [];
  for (const m of String(text || '').matchAll(/\[(\d{1,2}(?:\s*[,–-]\s*\d{1,2})*)\]/g)) {
    for (const part of m[1].split(/\s*,\s*/)) {
      const r = part.match(/^(\d+)\s*[–-]\s*(\d+)$/);
      if (r) { for (let k = Number(r[1]); k <= Number(r[2]) && k - Number(r[1]) < 20; k++) out.push(k); } else out.push(Number(part));
    }
  }
  return out;
}

function sentences(text) {
  return String(text || '').replace(/\s+/g, ' ').trim()
    .split(/(?<=[.!?](?:\s*\[[\d,\s–-]+\])*)\s+(?=[A-Z"“'(])/)
    .map((s) => s.trim()).filter((s) => s.length > 0);
}

// answer-check.js skips whole numbers up to 20 (too many false alarms in chat).
// Here a small whole number written as money or a rate is checked too. Measured
// 2026-10-12, Q2: "over $12/hr on reserved AWS instances" went through, but the
// item gives $12.29/hr for Azure (AWS: $6.88). Larger and decimal figures are
// already checked by unsupportedFacts.
const SMALL_MONEY = /(?:[$€£৳]|\b(?:usd|bdt|tk|inr|eur)\s?)(\d{1,2})(?![\d.,])(?!\s*(?:million|billion|thousand|mn|bn|[mbk]\b))|(?<![\d.,])\b(\d{1,2})(?![\d.,])\s*(?:\/\s*(?:hr|hour|h|month|mo|year|yr|gpu|card)\b|per (?:hour|month|year|gpu|card)\b)/gi;
function smallMoney(sentence, evidence, question) {
  const ev = String(evidence || '').replace(/(\d),(?=\d{3}\b)/g, '$1');
  const q = String(question || '');
  const missing = [];
  for (const m of String(sentence || '').matchAll(SMALL_MONEY)) {
    const n = m[1] || m[2];
    if (Number(n) > 20) continue;   /* unsupportedFacts covers these */
    // the number must appear in the same form: "$12" as money, "12/hr" as a rate.
    // A bare "12" elsewhere in a long article (a table row, "12 months") let Q2's
    // "$12/hr" through on the full text, 2026-10-13.
    const num = '(?<![\\d.,])' + n + '(?![\\d]|[.,]\\d)';
    const form = m[1]
      ? new RegExp('(?:[$€£৳]|\\b(?:usd|bdt|tk|inr|eur)\\s?)\\s?' + num + '|' + num + '\\s?(?:dollars|usd|taka)\\b', 'i')
      : new RegExp(num + '\\s*(?:\\/|per\\b)', 'i');
    if (new RegExp(num).test(q) || form.test(ev)) continue;
    missing.push(m[0].trim());
  }
  return missing;
}

const SAYS_NOTHING =/\b(do(es)? not|don.t|doesn.t|no item|none of the items|not (say|cover|mention|address)|(has|have) nothing (on|about)|no (items?|coverage|information|reporting) (on|about))\b/i;

function checkSynth(answer, items, question) {
  const byN = new Map((items || []).map((it) => [Number(it.n), it]));
  const a = String(answer || '').trim();
  const problems = [];
  if (!a) return { ok: false, problems: ['empty answer'], cited: [] };
  if (NOT_IN_FEED.test(a)) return { ok: true, problems, uncited: [], cited: [], nothing: true };
  const all = citations(a);
  const bad = [...new Set(all.filter((n) => !byN.has(n)))];
  if (bad.length) problems.push('cites items that do not exist: ' + bad.map((n) => '[' + n + ']').join(' '));
  if (!all.length && !SAYS_NOTHING.test(a)) problems.push('no citations at all');
  const uncited = [];
  for (const s of sentences(a)) {
    const cs = citations(s).filter((n) => byN.has(n));
    if (!cs.length) {
      if (!SAYS_NOTHING.test(s) && s.length >= 25) uncited.push(s);
      continue;
    }
    const ev = cs.map((n) => { const it = byN.get(n); return itemTitle(it) + ' ' + (it.summary || '') + ' ' + evidenceText(it.evidence); }).join(' ');
    const plain = s.replace(/\[[\d,\s–-]+\]/g, '');
    const miss = unsupportedFacts(plain, ev, question).concat(smallMoney(plain, ev, question));
    if (miss.length) problems.push('figures not in the cited items: ' + miss.join(', ') + ' (in: "' + s.slice(0, 80) + '")');
  }
  if (uncited.length) problems.push(uncited.length + ' sentence(s) without an item number: "' + uncited[0].slice(0, 80) + '"');
  return { ok: problems.length === 0, problems, uncited, cited: [...new Set(all.filter((n) => byN.has(n)))] };
}

// Second failure, but the only fault is a sentence or two without a number:
// drop those sentences rather than throw the whole answer away.
function salvage(answer, check) {
  if (!check || check.ok) return answer;
  if (check.problems.some((p) => !/without an item number/.test(p))) return '';
  const kept = sentences(answer).filter((s) => !check.uncited.includes(s));
  return kept.length >= 2 ? kept.join(' ') : '';
}

// ---- the second reading: is each sentence supported by the items it cites? ----
// The checks above catch wrong numbers and missing citations, not a true fact
// pinned to the wrong thing. Measured 2026-10-13, Q7 (twice): the item says the
// EU AI Act sets documentation duties for general-purpose models and, separately,
// that Article 13 covers high-risk systems; the answer said "Article 13 mandates
// that developers disclose training methodologies ... for these [general-purpose]
// models". Every word was in the item. A second call (thinking off) reads each
// sentence against only the items it cites.

const VERIFY_EV = 1500;
const VERIFY_SYSTEM = 'You check an answer against its sources. For each numbered sentence, read ONLY the source items it cites. ' +
  'supported = true only if every fact in the sentence is stated in those items: names, numbers, dates, who did what, and what applies to what. ' +
  'supported = false if the sentence attaches a fact to the wrong person, company, country, law, article, product or year; ' +
  'if it joins two facts the items keep separate into a claim they do not make; if it reverses or overstates what the items say; ' +
  'or if it adds a fact the items do not contain. Wording may differ; meaning may not. ' +
  'In why, name the exact fact that is wrong or missing, or write "ok".';

const VERIFY_SCHEMA = { type: 'json_schema', json_schema: { name: 'verdicts', strict: true, schema: {
  type: 'object', additionalProperties: false, required: ['verdicts'],
  properties: { verdicts: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['n', 'why', 'supported'],
    properties: { n: { type: 'integer' }, why: { type: 'string' }, supported: { type: 'boolean' } } } } } } } };

// The sentences worth checking: those that cite an item. Honest "the feed has
// nothing on X" sentences carry no claim to check.
function claimSentences(answer, items) {
  const have = new Set((items || []).map((it) => Number(it.n)));
  return sentences(answer).map((s) => ({ s, cites: [...new Set(citations(s))].filter((n) => have.has(n)) }))
    .filter((x) => x.cites.length);
}

function verifyBody(model, answer, items) {
  const claims = claimSentences(answer, items);
  const byN = new Map((items || []).map((it) => [Number(it.n), it]));
  const used = [...new Set(claims.flatMap((c) => c.cites))].sort((a, b) => a - b);
  const sources = used.map((n) => { const it = byN.get(n);
    return '[' + n + '] ' + itemTitle(it) + '\nSummary: ' + String(it.summary || '').replace(/\s+/g, ' ').trim() +
      '\nText: ' + evidenceText(it.evidence).replace(/\s+/g, ' ').trim().slice(0, VERIFY_EV); }).join('\n\n');
  const list = claims.map((c, i) => (i + 1) + '. ' + c.s).join('\n');
  return { model, temperature: 0, reasoning_effort: 'none', max_tokens: 200 + 120 * claims.length, response_format: VERIFY_SCHEMA,
    messages: [{ role: 'system', content: VERIFY_SYSTEM },
      { role: 'user', content: 'Source items:\n' + sources + '\n\nSentences to check:\n' + list }] };
}

// -> { unsupported: [{ s, why }], checked: n, parsed: bool }. A reply that cannot
// be read flags nothing (the answer has already passed the code checks).
function parseVerify(content, answer, items) {
  const claims = claimSentences(answer, items);
  let v = null;
  try { v = JSON.parse(String(content || '').replace(/^```(json)?|```$/g, '').trim()).verdicts; } catch (e) {}
  if (!Array.isArray(v)) return { unsupported: [], checked: claims.length, parsed: false };
  const unsupported = v.filter((x) => x && x.supported === false && claims[x.n - 1])
    .map((x) => ({ s: claims[x.n - 1].s, why: String(x.why || '').slice(0, 200) }));
  return { unsupported, checked: claims.length, parsed: true };
}

// Problems in the form the rewrite prompt takes.
function verifyProblems(result) {
  return (result.unsupported || []).map((u) => 'not supported by its items: "' + u.s.slice(0, 90) + '" (' + u.why + ')');
}

// ---- what happens to a flagged sentence (Wasim's chain, 2026-10-13) ----
// fix it with the checker's reason -> check the fix -> else quote the source
// line it rests on -> else drop it and say so. Nothing unchecked reaches him.

const FIX_SYSTEM = 'Rewrite ONE sentence so it says only what the cited source items state. ' +
  'A checker found this problem with it: the reason is given. Fix exactly that problem, keep everything else that is supported, ' +
  'and end the sentence with the same item numbers in brackets. Reply with the one sentence only. ' +
  'If no version of the sentence is supported by the items, reply exactly: DROP';

function fixBody(model, sentence, why, items) {
  const cites = [...new Set(citations(sentence))];
  const byN = new Map((items || []).map((it) => [Number(it.n), it]));
  const sources = cites.filter((n) => byN.has(n)).map((n) => { const it = byN.get(n);
    return '[' + n + '] ' + itemTitle(it) + '\nSummary: ' + String(it.summary || '').replace(/\s+/g, ' ').trim() +
      '\nText: ' + evidenceText(it.evidence).replace(/\s+/g, ' ').trim().slice(0, VERIFY_EV); }).join('\n\n');
  return { model, temperature: 0, reasoning_effort: 'none', max_tokens: 300,
    messages: [{ role: 'system', content: FIX_SYSTEM },
      { role: 'user', content: 'Source items:\n' + sources + '\n\nSentence: ' + sentence + '\n\nProblem: ' + why }] };
}

// the model's fix, or '' (DROP, empty, or it lost its item numbers)
function readFix(content, sentence) {
  const t = String(content || '').trim().replace(/^["“]|["”]$/g, '').split(/\n/)[0].trim();
  if (!t || /^drop\b/i.test(t)) return '';
  return citations(t).length ? t : '';
}

const STOP = new Set('about after again their there these those which while where would could should other being between through during before under above below every within without across along among around because against toward towards since until still also just more most much many such some than that this with from have were been into over only very what when your will them then they each both same well like'.split(' '));
function contentWords(t) {
  return new Set((String(t || '').toLowerCase().match(/[a-z][a-z0-9-]{3,}/g) || []).filter((w) => !STOP.has(w)));
}

// The source sentence the flagged one most likely rests on, verbatim, as
// '[6] says: "..."'. Markdown tables and link lists are skipped; at least 3
// shared content words, or nothing.
function bestQuote(sentence, items) {
  const want = contentWords(sentence.replace(/\[[\d,\s–-]+\]/g, ''));
  const byN = new Map((items || []).map((it) => [Number(it.n), it]));
  let best = null;
  for (const n of new Set(citations(sentence))) {
    const it = byN.get(n);
    if (!it) continue;
    const text = String(it.summary || '') + ' ' + evidenceText(it.evidence);
    for (const raw of text.split(/(?<=[.!?])\s+|\n+|\s…\s/)) {
      const s = raw.replace(/[#*_`|>]+/g, ' ').replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/\s+/g, ' ').trim();
      if (s.length < 30 || s.length > 300 || /https?:\/\//.test(s)) continue;
      const hit = [...contentWords(s)].filter((w) => want.has(w)).length;
      if (hit >= 3 && (!best || hit > best.hit)) best = { n, s, hit };
    }
  }
  return best ? '[' + best.n + '] says: "' + best.s + '"' : '';
}

function replaceSentence(answer, oldS, newS) {
  const ss = sentences(answer);
  const k = ss.indexOf(oldS);
  if (k < 0) return answer;
  if (newS) ss[k] = newS; else ss.splice(k, 1);
  return ss.join(' ');
}

const DROP_NOTE = (k) => '(' + k + ' sentence' + (k === 1 ? '' : 's') + ' removed: I could not confirm ' + (k === 1 ? 'it' : 'them') + ' against the sources.)';

// One flagged sentence's fate. fixes: [{ s, fix, fixOk }] — fix = the model's
// rewrite ('' if it said DROP), fixOk = the rewrite passed its own check.
// -> { answer, fixed, quoted, dropped }. Measured 2026-10-13 on 23 flagged
// sentences: 19 fixed, 4 quoted, 0 dropped; every real error came out right.
function applyFixes(answer, fixes, items) {
  let a = String(answer || '');
  let fixed = 0, quoted = 0, dropped = 0;
  for (const f of fixes || []) {
    if (f.fix && f.fixOk) { a = replaceSentence(a, f.s, f.fix); fixed++; continue; }
    const q = bestQuote(f.s, items);
    if (q) { a = replaceSentence(a, f.s, q); quoted++; } else { a = replaceSentence(a, f.s, ''); dropped++; }
  }
  if (dropped) a += ' ' + DROP_NOTE(dropped);
  return { answer: a, fixed, quoted, dropped };
}

// Second failure: drop the unsupported sentences if at least two cited ones remain.
function dropUnsupported(answer, result) {
  const bad = new Set((result.unsupported || []).map((u) => u.s));
  const kept = sentences(answer).filter((s) => !bad.has(s));
  return kept.filter((s) => citations(s).length).length >= 2 ? kept.join(' ') : '';
}

// ---- the reply ----

function sourceList(items) {
  return (items || []).slice(0, SYNTH_MAX_ITEMS).map((it) => it.n + '. ' + itemTitle(it) +
    (it.published_at ? ' (' + String(it.published_at).slice(0, 10) + ')' : '')).join('\n');
}

function thinNote(count) {
  return count <= 2 ? 'Your feed has only ' + count + ' item' + (count === 1 ? '' : 's') + ' on this:\n' : '';
}

function formatSynth(answer, items) {
  const shown = (items || []).slice(0, SYNTH_MAX_ITEMS);
  return thinNote(shown.length) + String(answer || '').trim() + '\n\nSources:\n' + sourceList(shown);
}

// The reply and the items it shows (whose 👍/👎 buttons go with it). "Nothing"
// shows no items: the closest ones were judged off the question. That wording
// is also what lets Fix 2 answer from the web, as it does for the agent.
// The 9B rarely uses the marker; it hedges instead ("The item notes a dataset
// includes quantum firms [1]. The items do not cover the Kenyan context."). An
// answer that says the items miss the question and has at most one real cited
// sentence is treated as nothing (measured 2026-10-12, Q12 twice).
const MISSES = /\b(do(es)? not (cover|answer|address|discuss|mention|include)|cannot answer|can.t answer|nothing (on|about|to say)|no (information|data|details|reporting|items?|coverage) (on|about|regarding|for))\b/i;
function answersNothing(answer) {
  const a = String(answer || '').trim();
  if (NOT_IN_FEED.test(a)) return true;
  const ss = sentences(a);
  const real = ss.filter((s) => citations(s).length && !MISSES.test(s) && !SAYS_NOTHING.test(s)).length;
  return ss.some((s) => MISSES.test(s)) && real <= 1;
}

function finalReply(answer, items) {
  if (answersNothing(answer)) return { output: NOTHING_REPLY, items: [] };
  const shown = (items || []).slice(0, SYNTH_MAX_ITEMS);
  return { output: formatSynth(answer, shown), items: shown };
}

// No usable answer: the items as a plain numbered list, as the agent would give.
function formatFallback(items) {
  const shown = (items || []).slice(0, SYNTH_MAX_ITEMS);
  if (!shown.length) return 'Your feed has nothing on this yet.';
  return thinNote(shown.length) + 'I could not write a checked summary, so here are the items:\n' +
    shown.map((it) => it.n + '. ' + itemTitle(it) + ' — ' + String(it.summary || '').split(/(?<=\.)\s/)[0]).join('\n');
}

// what the router passes WF-31 as the topic: the question minus its lead-in
function synthTopic(question) {
  // A comparison searches each side separately (WF-31 gives every "|" topic a
  // fair share). Measured 2026-10-12: "compare Bangladesh and Nigeria on AI
  // regulation" as one topic came back all Bangladesh, and the answer never said
  // the feed had nothing on Nigeria.
  const q0 = String(question || '').trim().replace(/[?!.]+\s*$/, '');
  const cmp = q0.match(/^(?:please\s+)?(?:compare|comparing|contrast)\s+(.+?)\s+(?:and|with|vs\.?|versus|to|against)\s+(.+?)(?:\s+(?:on|in|for|over|regarding|when it comes to)\s+(.+))?$/i) ||
    q0.match(/^(.+?)\s+(?:vs\.?|versus)\s+(.+?)(?:\s+(?:on|in|for|over)\s+(.+))?$/i);
  if (cmp) return cmp[3] ? cmp[1] + ' ' + cmp[3] + ' | ' + cmp[2] + ' ' + cmp[3] : cmp[1] + ' | ' + cmp[2];
  return String(question || '').trim()
    .replace(/^\s*(hey|hi|so|ok(ay)?|and|also)[,!\s]+/i, '')
    .replace(/^(can you |could you |please )?(give me |tell me )?(an? )?(quick |short |brief )?(overview|summary|rundown|gist|big picture)( of| on| about)?\s*/i, '')
    .replace(/^what('?s| is| are)\s+(happening|going on|changing|new)\s+(with|in|on|around|for|across)\s+/i, '')
    .replace(/^what('?s| is) the (state|status|latest|story|picture|situation) (of|on|with|in)\s+/i, '')
    .replace(/^summari[sz]e\s+(what (my|the) feed (says|has) (on|about)\s+)?/i, '')
    .replace(/^what (do|does) (my|the) (feed|items|articles|sources) (say|have) (about|on)\s+/i, '')
    .replace(/^what are the (main|key|latest|big|major) (developments|debates|arguments|issues|questions|risks|players|moves) (in|on|around|about|with)\s+/i, '')
    .replace(/[?!.]+\s*$/, '')
    .trim();
}

// A "yes" / "no" to the bot's full-sweep question is handled in code, not by
// the 9B (2026-10-16). Given "yes", the 9B called no tool and said "the full
// sweep returned 10 items"; the guard's redo then searched the feed for "yes"
// and the 9B presented those 10 unrelated items as sweep results. Nothing ran.
// Given "no", the reply fell through to a web search he had just declined.

// WF-40's own wording ("Needs confirmation"), echoed by the agent
const OFFER = /Run a full sweep on (.+?)\? It hits exa/i;
// same list as WF-40's Gate input, so the gate agrees with this routing
const YES = /^(yes|y|yeah|yep|yup|sure|ok|okay|go ahead|go for it|do it|run it|confirm(ed)?|please( do)?)\b/i;
const NO = /^(no|n|nope|nah|don'?t|do not|cancel|skip( it)?|not now|never ?mind|stop)\b/i;

// the query the bot's last message offered to sweep, '' for the default beat,
// null when the last message was not a sweep offer
function sweepOffer(lastBot) {
  const m = OFFER.exec(String(lastBot || ''));
  if (!m) return null;
  const q = m[1].trim();
  return /^the default beat$/i.test(q) ? '' : q;
}

// 'go' | 'no' | '' for this message, given the bot's previous one
function sweepDecision(text, lastBot) {
  const offered = sweepOffer(lastBot);
  if (offered === null) return { sweep: '', sweep_query: '' };
  const msg = String(text || '').trim();
  if (msg.length < 60 && YES.test(msg)) return { sweep: 'go', sweep_query: offered };
  if (msg.length < 40 && NO.test(msg)) return { sweep: 'no', sweep_query: offered };
  return { sweep: '', sweep_query: '' };
}

const SOURCE_NAMES = { 'Run Exa': 'exa', 'Run Tavily': 'tavily', 'Run Brave': 'brave', 'Run RSS': 'rss' };

// The reply, from what WF-40 actually returned. Never claims items it did not get.
function sweepReply(decision, result) {
  const topic = decision.sweep_query ? ' on ' + decision.sweep_query : '';
  if (decision.sweep === 'no') return 'OK, no sweep' + topic + '. Nothing was run.';
  const r = result || {};
  if (r.status === 'not_run') return "The sweep didn't run: it was not confirmed. Ask for it again and reply yes.";
  const parts = Array.isArray(r.sweep) ? r.sweep : [];
  if (!parts.length) return "The sweep" + topic + " failed before any source ran. Nothing was added.";
  let total = 0;
  const per = [], failed = [];
  for (const p of parts) {
    const name = SOURCE_NAMES[p.source] || p.source;
    if (p.error || p.status === 'failed') { failed.push(name); continue; }
    const n = Number(p.items_created) || 0;
    total += n;
    per.push(name + ' ' + n);
  }
  const lines = ['Full sweep' + topic + ' finished: ' + (total ? total + ' new item' + (total === 1 ? '' : 's') : 'nothing new') + ' added' + (per.length ? ' (' + per.join(', ') + ')' : '') + '.'];
  if (failed.length) lines.push(failed.join(', ') + ' failed.');
  if (total) lines.push('Ask "anything on ' + (decision.sweep_query || 'today') + '" to see them.');
  return lines.join('\n');
}

// Fix 1a (on trial 2026-10-12): every figure and name in a reply must appear
// in what the tools returned this turn. Inlined into WF-00's Guard check and
// Final check.
//
// Why: the 9B fills gaps from memory — "Anthropic adds 512 tokens" (the
// article says 50-100), "Harvey raised $15M in a seed round". Figures are the
// most common invention and the easiest to check: a number either appears in
// the evidence or it does not.
// Limit: a real name in the wrong place passes — "Langfuse was acquired by
// Databricks" names a company that IS in the same article (it bought someone
// else). Catching that needs a model judging each claim, not string matching.

const NAME_STOP = new Set(('I The This That These Those It Its If In On At For From To Of And Or But So As By With Without Yes No Not ' +
  'AI Would Do Does Did Is Are Was Were Be Can Could Should Will Also Here There What Which Who When Where Why How ' +
  'Based According Under Over After Before Since During While Both Each Every Some Any All Most Many More Less Other ' +
  'Feed Item Items Article Articles Source Sources Summary Evidence Passage Note Older Latest Recent New Score ' +
  'Telegram Overseer Exa Tavily Brave RSS Want Shall Let Sure OK Okay Please Thanks Here ' +
  // dates get reworded ("January" for "Jan"); they are not names
  'January February March April May June July August September October November December ' +
  'Jan Feb Mar Apr Jun Jul Aug Sep Sept Oct Nov Dec Monday Tuesday Wednesday Thursday Friday Saturday Sunday').split(' ').map((w) => w.toLowerCase()));

// Same spelling for "$1.2 billion" / "$1.2B" / "1,200" / "40–60 percent".
// Evidence often arrives as JSON text, where a line break is the two
// characters \n: "$581.7\n\nbillion" in a PDF report did not match "$581.7B"
// in the matrix runs (2026-10-12), so escapes and runs of whitespace go first.
function norm(s) {
  return String(s || '').toLowerCase()
    .replace(/\\[nrt]/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/[‐-―−]/g, '-')
    .replace(/(\d),(?=\d{3}\b)/g, '$1')
    .replace(/\$\s?/g, '')
    .replace(/(\d)\s?(billion|bn)\b/g, '$1b')
    .replace(/(\d)\s?(million|mn)\b/g, '$1m')
    .replace(/(\d)\s?(thousand)\b/g, '$1k')
    .replace(/(\d)\s?(percent|per cent)\b/g, '$1%')
    .replace(/(\d)\s+(%|b|m|k)\b/g, '$1$2')
    // amounts as full numbers: "$400K" and "$400,000" (a matrix false alarm) both become 400000
    .replace(/(\d+(?:\.\d+)?)(k|m|b)\b/g, (x, n, u) => String(Math.round(Number(n) * { k: 1e3, m: 1e6, b: 1e9 }[u])));
}

const esc = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Figures: numbers with an optional unit. Skipped: small bare counts (list
// numbers, item n), years, and anything the question itself contains.
function figures(text, question) {
  const q = norm(question);
  const out = new Set();
  for (const m of norm(text).matchAll(/(?<![\w.])(\d+(?:\.\d+)?)(%|b|m|k|x)?(?![\w])/g)) {
    const num = Number(m[1]), tok = m[1] + (m[2] || '');
    if (!m[2] && num <= 20 && !m[1].includes('.')) continue;
    if (!m[2] && num >= 1990 && num <= 2035 && !m[1].includes('.')) continue;
    if (new RegExp('(?<![\\d.])' + esc(tok) + '(?![\\d])').test(q)) continue;
    out.add(tok);
  }
  return [...out];
}

// Names: capitalised words that do not start a sentence or a list line.
function names(text, question) {
  const q = norm(question);
  const out = new Set();
  const t = String(text || '').replace(/\*\*|__|`/g, '');
  for (const m of t.matchAll(/(?<=[a-z0-9,;:()"'’] )([A-Z][A-Za-z0-9&-]*[A-Za-z0-9](?: [A-Z][A-Za-z0-9&-]*[A-Za-z0-9])*)/g)) {
    const words = m[1].split(' ').filter((w) => !NAME_STOP.has(w.toLowerCase()) && w.length > 1);
    if (!words.length) continue;
    const name = words.join(' ');
    if (q.includes(name.toLowerCase())) continue;
    out.add(name);
  }
  return [...out];
}

// What in the reply is not in the evidence. A figure must appear as written
// (after norm). Names are opt-in: in the matrix runs (2026-10-12) the name
// check raised only false alarms — bullet headings ("Levers", "Thresholds"),
// "Liberation Army" for "People's Liberation Army" — and replaced one good
// answer, while the invention it was meant for ("Databricks") passes anyway.
function unsupportedFacts(reply, evidence, question, opts) {
  const ev = norm(evidence);
  const missing = [];
  for (const f of figures(reply, question)) {
    if (!new RegExp('(?<![\\d.])' + esc(f) + '(?![\\d])').test(ev)) missing.push(f);
  }
  if (opts && opts.names) {
    for (const n of names(reply, question)) {
      if (!n.toLowerCase().split(' ').some((w) => ev.includes(w))) missing.push(n);
    }
  }
  return missing;
}

// "summarize the video without the timestamps" (2026-10-18): the router read
// "summarize" as a big-picture question and WF-45 wrote an overview of every
// feed item with "video" in it (an n8n tutorial, a Mod Sun music video...).
// Three gaps, fixed together:
//   1. messages sent outside the agent (WF-20 media/link summaries, WF-43
//      re-sends) never reached chat memory or chat_results, so "the video" had
//      nothing to point at -> botSaidSql records every such send;
//   2. keyword routes (synth) ran before anyone asked whether the message points
//      at something already shown -> refRoute runs first, in code;
//   3. "without the timestamps" had nowhere to go -> itemBody/itemAnswer rewrite
//      the one item as asked, from its own text only, figure-checked.
// Inlined into WF-00 (routing, answer), WF-20 and WF-43 (recording).
// Needs unsupportedFacts from answer-check.js inlined first (itemAnswer only).

// things the bot shows one of; plurals ("the videos about agents") are topics
const REF_NOUN = '(?:video|clip|talk|podcast|episode|article|story|item|link|page|piece|post|paper|report|thread|interview|one|result|transcript)';
// "the video", "that article", "this one", "the last link"
const REF_PHRASE = new RegExp('\\b(?:the|that|this|your|ur)\\s+(?:last\\s+|latest\\s+|previous\\s+|same\\s+)?' + REF_NOUN + '\\b(?![-\'’]?s\\b)', 'i');
// ...followed by a description: may be a search, so the agent decides
const REF_DESCRIBED = new RegExp(REF_PHRASE.source + '\\s+(?:about|on|from|by|with|where|that|which|called|titled|named)\\b', 'i');
// "summarize it", "what does it say", "tell me more about that"
const REF_PRONOUN = new RegExp([
  '\\b(?:summari[sz]e|recap|explain|shorten|simplify|rewrite|redo|reformat|translate|tl;?dr|break down|go over|unpack)\\s+(?:it|this|that)\\b',
  '\\bwhat (?:does|did|is) (?:it|this|that) (?:say|said|cover|mean|about|argue|claim|conclude)',
  '\\b(?:more|tell me|anything else) (?:more )?(?:about|on) (?:it|this|that)\\b',
  // whole-message only: "is it worth it to switch to X" is a question of its own
  '^(?:so |and |but )?(?:is|was) (?:it|this|that) (?:worth (?:it|watching|reading|a look)|any good|legit|accurate)\\s*[?.!]*$',
].join('|'), 'i');
// a bare instruction with nothing else in it: "summarize without timestamps", "shorter please"
const TRANSFORM_VERB = /^(?:can you |could you |please |pls |now |ok(?:ay)?,? )*(summari[sz]e|recap|shorten|simplify|rewrite|redo|reformat|tl;?dr|summary|shorter|simpler|briefer|again)\b/i;
const FORMAT_WORDS = /\b(?:without|with|no|minus|skip|drop|remove|the|a|an|any|all|in|into|as|to|of|for|me|just|only|please|pls|it|this|that|again|version|summary|plain|simple|simpler|short|shorter|brief|briefly|quick|quickly|english|text|prose|paragraphs?|bullets?|bullet points?|points?|lines?|sentences?|words?|timestamps?|time ?stamps?|times|links?|emojis?|numbers?|formatting|one|two|three|four|five|\d+)\b/gi;

// What the message points at, from its words alone:
//   'bare'      - one shown thing, no description ("summarize the video", "is it any good?")
//   'described' - a shown thing picked by description ("the article about nvidia")
//   ''          - not a reference; normal routing
function referentKind(text) {
  const t = String(text || '').trim();
  if (!t || /https?:\/\//i.test(t)) return '';
  if (REF_DESCRIBED.test(t)) return 'described';
  if (REF_PHRASE.test(t) || REF_PRONOUN.test(t)) return 'bare';
  const m = TRANSFORM_VERB.exec(t);
  if (m && !t.slice(m[0].length).replace(FORMAT_WORDS, ' ').replace(/[^a-z]+/gi, ' ').trim()) return 'bare';
  return '';
}

// the last list shown counts for this long
const REF_WINDOW_MIN = 120;

const MEDIA_NOUN = /\b(?:video|clip|talk|podcast|episode|interview|transcript)\b/i;
const MEDIA_URL = /youtube\.com\/watch|youtu\.be\/|vimeo\.com|soundcloud\.com|podcasts\.apple\.com|twitch\.tv|ted\.com\/talks|rumble\.com/i;

// The route, given the last list this chat was shown (chat_results, with each
// item's title and url in list order):
//   { route: 'item', n }  - it can only mean item n: answered here, in code
//                           (one item shown, or "the video" and one video shown)
//   { route: 'agent' }    - several fit: the agent picks with get_item, told the list
//   { route: '' }         - no reference, or nothing recent to refer to
function refRoute(text, list) {
  const kind = referentKind(text);
  const l = list || {};
  const items = Array.isArray(l.items) ? l.items : [];
  const n = Number(l.n) || items.length;
  const age = Number(l.age_min);
  if (!kind || !n || !(age >= 0 && age <= REF_WINDOW_MIN)) return { route: '' };
  if (kind === 'bare' && n === 1) return { route: 'item', n: 1 };
  if (kind === 'bare' && MEDIA_NOUN.test(text)) {
    const vids = items.map((it, k) => ({ k: k + 1, media: MEDIA_URL.test(String(it.url || '')) })).filter((x) => x.media);
    if (vids.length === 1) return { route: 'item', n: vids[0].k };
  }
  return { route: 'agent' };
}

// what the agent is told on the 'agent' route: the list itself (memory may not
// hold it: a WF-31 list is in memory only as the reply text, if at all)
function refNote(list) {
  const items = (list && Array.isArray(list.items) ? list.items : []).slice(0, 10);
  return '[This message points at something already shown in this chat. The last list shown: ' +
    (items.map((it, k) => (k + 1) + '. ' + String(it.title || it.url || '').slice(0, 120)).join('; ') || 'unknown') +
    '. If the message means one of these, call get_item with its number (never query_feed for it) and follow any format instruction in the message (shorter, no timestamps, bullets). If it fits none, ask which one they mean.]';
}

// Telegram HTML -> what he read, for memory
function plainText(html) {
  return String(html || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&').trim();
}

// One message the bot sent outside the agent: an ai memory row tagged with its
// source (Fix memory and the sweep check skip tagged rows: a video can arrive
// while an answer is being written), and, when it showed items, the chat's
// numbered list, so "#1" / "the video" resolve to it. base64 keeps web text out
// of the SQL (CLAUDE.md: '$785606.5' breaks the Postgres node).
function botSaidSql(chatId, html, itemIds, source) {
  const chat = String(chatId || '').trim();
  const text = plainText(html);
  if (!/^-?\d+$/.test(chat) || !text) return 'select 1 as skipped';
  const b64 = Buffer.from(text, 'utf8').toString('base64');
  const src = String(source || 'system').replace(/[^a-z0-9_-]/gi, '');
  const ids = (itemIds || []).map(Number).filter((x) => Number.isInteger(x) && x > 0);
  const mem = "insert into n8n_chat_histories (session_id, message) values ('" + chat + "', jsonb_build_object('type', 'ai', 'content', " +
    "convert_from(decode('" + b64 + "', 'base64'), 'UTF8'), 'tool_calls', '[]'::jsonb, 'invalid_tool_calls', '[]'::jsonb, " +
    "'additional_kwargs', jsonb_build_object('source', '" + src + "'), 'response_metadata', '{}'::jsonb))";
  if (!ids.length) return mem + ' returning id';
  return 'with m as (' + mem + ' returning id) ' +
    'insert into chat_results (chat_id, item_ids, topic, created_at) values (' + chat + ', array[' + ids.join(',') + ']::bigint[], null, now()) ' +
    'on conflict (chat_id) do update set item_ids = excluded.item_ids, topic = excluded.topic, created_at = excluded.created_at returning (select id from m) as id';
}

// SQL filter for "rows the agent wrote" (untagged)
const AGENT_ROWS = "coalesce(message->'additional_kwargs'->>'source', '') = ''";

// the item's own words: summary, key points (times dropped), page text
function itemText(item) {
  const it = item || {};
  const pts = ((it.structured || {}).key_points || it.key_points || []).map((p) => '- ' + (p.point || p)).join('\n');
  return [it.title && 'Title: ' + it.title, it.summary && 'Summary: ' + it.summary, pts && 'Key points:\n' + pts,
    it.page_excerpt && 'Saved text (excerpt):\n' + String(it.page_excerpt).slice(0, 6000)].filter(Boolean).join('\n\n');
}

const ITEM_SYSTEM = 'You answer a request about ONE item the user was just shown (an article or video from their research feed). ' +
  'Use ONLY the item text given. Follow the request\'s format instructions exactly (e.g. no timestamps, shorter, bullets, plain prose). ' +
  'Never add facts, names or numbers that are not in the item text; if it does not say, say so. ' +
  'Plain text, no markdown, no timestamps unless asked. Start with the answer, not with "Sure".';

// LM Studio body, thinking off (reasoning_effort none: CLAUDE.md, Models)
function itemBody(model, request, item) {
  return { model, temperature: 0, reasoning_effort: 'none', max_tokens: 900,
    messages: [{ role: 'system', content: ITEM_SYSTEM },
      { role: 'user', content: 'Request: ' + String(request || '') + '\n\nItem:\n' + itemText(item) }] };
}

// the stored summary with its points, no times: the answer when the 9B's fails
function plainSummary(item) {
  const it = item || {};
  const pts = ((it.structured || {}).key_points || it.key_points || []).map((p) => String(p.point || p).trim()).filter(Boolean);
  return [String(it.title || '').trim(), String(it.summary || '').trim(), pts.length ? 'Key points:\n' + pts.map((p) => '• ' + p).join('\n') : '']
    .filter(Boolean).join('\n\n');
}

// the 9B's answer if it holds up against the item, else the stored summary
function itemAnswer(content, item, request) {
  let out = String(content || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  const reason = !out ? 'empty' : unsupportedFacts(out, itemText(item), request).length ? 'unsupported figures' : '';
  if (reason) out = plainSummary(item);
  return { output: out || "I couldn't open that item again. Ask about it by name and I'll search the feed.", fallback: reason };
}

// ---- an instruction sent WITH the link (WF-43, 2026-10-18) ----
// "<link> summarize it without timestamps": the video's item, looked up by its
// canonical url (both texts base64: web text never goes into SQL as a literal),
// with the saved transcript, and the instruction echoed back so each row carries it.
function itemLookupSql(canonicalUrl, instruction) {
  const b = (s) => Buffer.from(String(s || ''), 'utf8').toString('base64');
  return "select f.id, f.title, f.summary, f.canonical_url, f.structured, " +
    "coalesce((select left(string_agg(dc.text, chr(10) || chr(10) order by dc.n), 6000) from doc_chunks dc where dc.raw_doc_id = f.raw_doc_id), '') as page_excerpt, " +
    "convert_from(decode('" + b(instruction) + "', 'base64'), 'UTF8') as instruction " +
    "from feed_items f where f.canonical_url = convert_from(decode('" + b(canonicalUrl) + "', 'base64'), 'UTF8') order by f.id desc limit 1";
}

// the Telegram message: the video's title, then the answer (HTML-escaped)
function answerMessage(item, answer) {
  const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  return ('\u{1F3AC} <b>' + esc((item || {}).title) + '</b>\n\n' + esc(answer)).slice(0, 4000);
}

// run_discovery starts a paid search (~6 minutes, items added to the real feed),
// so whether it may start is decided in code, not by the 9B (2026-10-18). The
// tool description says "only on an explicit search verb", and the 9B still
// called it for bare topics about once in 7: "quantum error correction
// breakthroughs" (execution 37070, run 102, 10 items) and "best sourdough
// starter recipe" (execution 34834). WF-00 computes searchAllowed in
// 'Big picture?' and passes it to WF-41 as a fixed input; WF-41 refuses an
// agent call without it. rss is not gated ("anything new today" is free).

// the verbs the system prompt promises, plus their plain variants
const SEARCH_VERB = /\b(search(ing)?( for| up)?|find me|look (it |that |this )?up|look up|go (and )?get|dig (into|up)|run (a |another )?(new )?(web )?(search|discovery)|do (a |another )?(web )?search|track(ing)?)\b/i;
// "don't search", "no need to look it up", "without searching"
const SEARCH_NEG = /\b(don'?t|do not|no need to|never|without|not)\s+(\w+\s+){0,2}$/i;
// a noun or a past question, not a request: "your last search", "did you search"
const SEARCH_NOT_ASK = /\b(the|your|my|last|that|this|previous|earlier)\s+$|\b(did|have|has|had)\s+(you|it|we)\s+$/i;
// the same yes list as WF-40's gate and shared/sweep-confirm.js
const SEARCH_YES = /^(yes|y|yeah|yep|yup|sure|ok|okay|go ahead|go for it|do it|run it|confirm(ed)?|please( do)?)\b/i;
// a bot question offering a search ("Want me to search for X?"); the prompt
// says never to offer one, but if it does, his yes counts as asking
const SEARCH_OFFER = /\b(search|look (it |that )?up|dig into|run (a )?(search|discovery))\b[^?]*\?/i;

function hasSearchVerb(text) {
  const msg = String(text || '');
  const re = new RegExp(SEARCH_VERB.source, 'gi');
  let m;
  while ((m = re.exec(msg))) {
    const before = msg.slice(0, m.index);
    if (!SEARCH_NEG.test(before) && !SEARCH_NOT_ASK.test(before)) return true;
  }
  return false;
}

// a short yes to the bot's previous message, when that message offered a search
function yesToSearch(text, lastBot) {
  const msg = String(text || '').trim();
  return msg.length < 60 && SEARCH_YES.test(msg) && SEARCH_OFFER.test(String(lastBot || ''));
}

function searchAllowed(text, lastBot) {
  return hasSearchVerb(text) || yesToSearch(text, lastBot);
}

// "deep search ..." starts a deep research job (WF-46), decided in code before the
// agent (2026-10-19). Only these words start it, never the 9B: a job holds the GPU
// for ~6 minutes and spends ~$0.09 of search credit. "dig into" stays with
// run_discovery (shared/search-gate.js).
// Names here are prefixed DEEP_/deep: 'Big picture?' inlines several shared files
// into one Code node, and two files declaring YES broke WF-00 on 2026-10-18.

// Only at the start ("deep search: X", "do a deep research on X") or the end
// ("X? deep dive please"): in the middle it is usually about something else
// ("what is deep research in chatgpt?").
const DEEP_CORE = '(?:(?:please|pls|can you|could you)\\s+)?(?:(?:do|run|start)\\s+(?:a|another|the)\\s+)?deep[\\s-]*(?:search|research|dive)';
const DEEP_TRIGGER = new RegExp('^\\s*' + DEEP_CORE + '(?:\\s+(?:on|into|for|about|of))?\\s*[:,\\-–—]?\\s*', 'i');
const DEEP_TRAILER = new RegExp('[\\s,.;:\\-–—]*\\b' + DEEP_CORE + '(?:\\s+(?:please|pls|on (?:that|this|it)|it))?[\\s.!?]*$', 'i');
// what is left when the message only points back ("deep search on that")
const DEEP_VAGUE = /^(?:(?:on|into|for|about)\s+)?(?:that|this|it|this one|that one|the last one|my (?:last )?question|the (?:same )?question)?\s*(?:please|pls|again)?[\s.!?]*$/i;

// -> { go: true, question } when the message asks for a deep search; question is ''
//    when it points back and there is no earlier message to point at
function deepAsk(text, lastHuman) {
  const t = String(text || '');
  const m = t.match(DEEP_TRIGGER) || t.match(DEEP_TRAILER);
  if (!m) return { go: false, question: '' };
  let q = (t.slice(0, m.index) + ' ' + t.slice(m.index + m[0].length)).replace(/\s+/g, ' ').trim().replace(/^[,.;:\-–—\s]+|[,;:\-–—\s]+$/g, '');
  if (q.length < 8 || DEEP_VAGUE.test(q)) q = String(lastHuman || '').trim();
  return { go: true, question: q.slice(0, 500) };
}

// #16 "Brief me" on demand (2026-10-21). Inlined into WF-00 ('Big picture?',
// 'Brief prep', 'Brief reply'). Decided in code, like deep search and the
// scorecard: the 9B picked its own time window for "brief me" (a week, or none).
//
// Wasim's calls: list only (no 9B summary on top), "anything new today?" stays
// the RSS run. A brief = the best stories that ARRIVED since his last brief
// (created_at, not the article's publish date: an older article saved today is
// new to him), one row per story, best score first, 5 at a time. The first
// brief looks back 7 days. A topic brief ("brief me on bangladesh") or an
// explicit window ("catch me up on this week") does not move the stored time.

const BRIEF_PAGE = 5;
const BRIEF_FIRST_DAYS = 7;

const BRIEF_WORDS = /^\s*(?:hey |ok |so |please )?(?:(?:can you |could you )?(?:give me |send me )?(?:a |my |the )?(?:brief(?:ing)?|recap|catch[- ]?up)(?: me)?|brief me|catch me up|what did i miss|fill me in|bring me up to (?:date|speed))\b/i;
const MORE_WORDS = /^\s*(?:more|next|next (?:5|five|page)|show (?:me )?more|the next (?:5|five)|keep going)\s*[.!?]*\s*$/i;
const WINDOW_WORDS = /\b(today|yesterday|this week|last week|past week|this month|last (\d{1,2}) days?|past (\d{1,2}) days?)\b/i;

// { go, more, topic, days } — days = an explicit window in days ('' = since the last brief)
function briefAsk(text, lastBot) {
  const t = String(text || '').trim();
  // only after a brief this module wrote: the agent copied the layout, "Say 'more'"
  // included, into a "brief me on bangladesh" reply (end to end, 2026-10-21)
  const lb = String(lastBot || '');
  // "more" after a topic brief pages that topic in code too: left to the agent it
  // invented three "Kaggle - ..." articles (end to end, 2026-10-21)
  if (MORE_WORDS.test(t) && /^(\d+ new stor(?:y|ies) since|More since|Best on |More on )/.test(lb) && /Say "more" for the next \d+/.test(lb))
    return { go: true, more: true, topic: '', days: '', topic_more: /^(Best on |More on )/.test(lb) };
  const m = t.match(BRIEF_WORDS);
  if (!m) return { go: false };
  let rest = t.slice(m[0].length);
  let days = '';
  const w = rest.match(WINDOW_WORDS);
  if (w) {
    const k = w[1].toLowerCase();
    days = k === 'today' ? '1' : k === 'yesterday' ? '2' : /week/.test(k) ? '7' : /month/.test(k) ? '30' : String(Number(w[2] || w[3]));
    rest = rest.replace(w[0], ' ');
  }
  const topic = rest
    .replace(/^[\s,:]*(?:on|about|with|for|regarding|re)\b/i, ' ')
    .replace(/\b(?:since|from|over|during|in|for|the|please|thanks?|me|everything|all)\b/gi, ' ')
    .replace(/[?!.,:;]+/g, ' ').replace(/\s+/g, ' ').trim();
  // A topic brief is searched by WF-31 (spelling, passages, rerank), not by
  // briefSql: on this week's 49 stories a one-word topic matched poorly there —
  // "funding" scored Modal's $16B Series D 0.28 by meaning, word matching pulled in
  // "India Reverse REPO Rate" (2026-10-21). Left to the 9B it skipped the search
  // once and answered from memory, so WF-00 calls WF-31 itself.
  return { go: true, more: false, topic, days };
}

// The stored state per chat: settings key brief:<chat> = { last, since, page, topic }.
function briefKey(chatId) { return 'brief:' + String(chatId).replace(/[^0-9-]/g, ''); }

function parseState(v) {
  try { const s = JSON.parse(String(v || '')); return s && typeof s === 'object' ? s : {}; } catch (e) { return {}; }
}

// What this brief covers and what gets stored. now = ISO string.
function briefPlan(ask, state, now) {
  const st = state || {};
  const nowMs = Date.parse(now);
  if (ask.more) {
    const page = Number(st.page || 0) + 1;
    return { since: st.since || new Date(nowMs - BRIEF_FIRST_DAYS * 864e5).toISOString(), topic: st.topic || '', page,
      store: { ...st, page }, from_last: Boolean(st.from_last) };
  }
  const explicit = ask.days !== '' && ask.days != null;
  const since = explicit ? new Date(nowMs - Number(ask.days) * 864e5).toISOString()
    : st.last || new Date(nowMs - BRIEF_FIRST_DAYS * 864e5).toISOString();
  const moves = !explicit && !ask.topic;   // only a plain brief moves "last"
  return { since, topic: ask.topic || '', page: 0, from_last: !explicit && Boolean(st.last),
    store: { last: moves ? now : (st.last || ''), since, page: 0, topic: ask.topic || '', from_last: !explicit && Boolean(st.last) } };
}

const sqlText = (s) => "convert_from(decode('" + Buffer.from(String(s || ''), 'utf8').toString('base64') + "', 'base64'), 'UTF8')";

// One row back: rows (json, this page), total, good (score 7+). Topic = all its
// words in title/summary/angle/tags (english stems) OR meaning (vec, cutoff).
function briefSql({ since, topic, page, vec, cutoff }) {
  const sinceMs = Date.parse(since);
  if (!Number.isFinite(sinceMs)) throw new Error('bad since: ' + since);
  const sinceLit = "'" + new Date(sinceMs).toISOString() + "'::timestamptz";
  const off = Math.max(0, Number(page) || 0) * BRIEF_PAGE;
  const t = String(topic || '').trim();
  const kw = t ? "(select bool_and(w = any(tsvector_to_array(to_tsvector('english', coalesce(s.title,'') || ' ' || coalesce(s.summary,'') || ' ' || coalesce(s.angle,'') || ' ' || coalesce(array_to_string(s.tags,' '),''))))) " +
    "from unnest(tsvector_to_array(to_tsvector('english', " + sqlText(t) + "))) w)" : 'true';
  const sim = t && vec ? " or (fi.embedding is not null and 1 - (fi.embedding <=> '" + vec + "'::vector) >= " + Number(cutoff) + ')' : '';
  return 'with s as (select s.*, fi.id from feed_stories s ' +
    'left join lateral (select id, embedding from feed_items f where f.canonical_url = s.canonical_url order by f.id desc limit 1) fi on true ' +
    'where s.created_at >= ' + sinceLit + (t ? ' and (coalesce(' + kw + ', false)' + sim + ')' : '') + '), ' +
    'p as (select id, title, canonical_url, angle, summary, score, articles, created_at from s order by score desc nulls last, created_at desc limit ' + BRIEF_PAGE + ' offset ' + off + ') ' +
    "select (select json_agg(p order by p.score desc nulls last, p.created_at desc)::text from p) as rows, " +
    '(select count(*) from s)::int as total, (select count(*) from s where score >= 7)::int as good';
}

function fmtWhen(iso) {
  const d = new Date(Date.parse(iso) + 6 * 3600e3);   // Asia/Dhaka, UTC+6, no DST
  const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return days[d.getUTCDay()] + ' ' + d.getUTCDate() + ' ' + months[d.getUTCMonth()] + ' ' +
    String(d.getUTCHours()).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0');
}

// The reply, and the items (n continues across pages, so "#7" works after "more").
function briefReply(plan, rows, total, good) {
  const list = Array.isArray(rows) ? rows : [];
  const tot = Number(total) || 0, gd = Number(good) || 0;
  const scope = (plan.topic ? ' on ' + plan.topic : '') + ' since ' + (plan.from_last ? 'your last brief (' + fmtWhen(plan.since) + ')' : fmtWhen(plan.since));
  if (!tot) return { output: 'Nothing new' + scope + '.', items: [] };
  const first = plan.page * BRIEF_PAGE;
  if (!list.length) return { output: 'That was all of them: ' + tot + ' new ' + (tot === 1 ? 'story' : 'stories') + scope + '.', items: [] };
  const items = list.map((r, i) => ({ n: first + i + 1, id: Number(r.id), title: r.title, canonical_url: r.canonical_url }));
  const lines = list.map((r, i) => (first + i + 1) + '. ' + String(r.title || r.canonical_url || '').trim() +
    (Number(r.articles) > 1 ? ' (' + r.articles + ' sources)' : '') + ' [' + (r.score == null ? '–' : r.score) + ']' +
    (r.angle ? '\n   ' + String(r.angle).replace(/\s+/g, ' ').trim().slice(0, 220) : ''));
  const head = plan.page ? 'More' + scope + ' (' + (first + 1) + '–' + (first + list.length) + ' of ' + tot + '):'
    : tot + ' new ' + (tot === 1 ? 'story' : 'stories') + scope + ', ' + gd + ' scored 7+.' + (tot > list.length ? ' Best ' + list.length + ':' : '');
  const left = tot - (first + list.length);
  return { output: head + '\n\n' + lines.join('\n') + (left > 0 ? '\n\nSay "more" for the next ' + Math.min(BRIEF_PAGE, left) + '.' : ''), items };
}

// "brief me on X": WF-31's best matches on X (any date), in WF-31's order, in the
// brief's layout. "more" asks WF-31 for one more page (limit grows, one extra row
// says whether there is a next page); WF-31 numbers and stores the whole list, so
// "#7" works after "more".
function briefTopicLimit(page) { return String((Number(page) + 1) * BRIEF_PAGE + 1); }

function briefTopicReply(topic, result, page) {
  const r = result || {};
  const p = Number(page) || 0;
  const all = Array.isArray(r.items) ? r.items : [];
  const items = all.slice(p * BRIEF_PAGE, (p + 1) * BRIEF_PAGE);
  if (!all.length) return { output: 'Your feed has nothing on ' + topic + ' yet.', items: [], empty: true };
  if (!items.length) return { output: 'That was everything on ' + topic + '.', items: [] };
  const lines = items.map((it) => it.n + '. ' + String(it.title || it.canonical_url || '').trim() +
    (Number(it.articles) > 1 ? ' (' + it.articles + ' sources)' : '') + ' [' + (it.score == null ? '–' : it.score) + ']' +
    (it.angle ? '\n   ' + String(it.angle).replace(/\s+/g, ' ').trim().slice(0, 220) : ''));
  const fixed = r.spelling ? ' (' + String(r.spelling).replace(/\s*—.*$/, '') + ')' : '';
