parameters.jsCode:
// Decides whether the router's reply must be thrown away and redone with a forced
// fresh lookup. Inlined into WF-00's "Guard check" node.
//
// Why it exists (measured 2026-10-09): with thinking off, local Qwen3.5-9B skips
// the tools whenever the chat already holds an answer to a similar question — it
// repeats the old answer, or invents one ("the feed has nothing on Nvidia" with 10
// items saved). Prompt wording, memory tidying and history logs all failed to stop
// it; this check is the part the model cannot talk its way past.
//
// Rule: a reply that makes claims about the feed, or claims to have started an
// action, is only acceptable if a tool actually ran this turn. Sources and runs are
// exempt: they are handed to the model fresh every message, so answering those from
// context is correct.
// "How are my sources doing?" is about source QUALITY (WF-34 scorecard), not run
// status. Measured 2026-10-12: with thinking off the 9B answered 4/4 phrasings
// from the run list in its context and never called the scorecard, so the guard
// routes it deterministically (WF-00 runs the scorecard before the redo).
function sourceQualityQ(question) {
  const q = String(question || '').replace(/\bopen[- ]source\b/gi, '');
  if (/\bhow (are|is|did|have|has) (my |the |our |all )?(rss |search )?(sources?|feeds?)\b/i.test(q)) return true;
  const subject = /\b(sources?|feeds?|rss|exa|brave|tavily|search engines?|providers?)\b/i.test(q);
  const quality = /\b(doing|worth|useful|useless|perform\w*|quality|good|best|worst|better|compare[ds]?|comparison|scorecard|score|pay(ing)?|keep(ing)?|drop|cut|value|deliver\w*|produc\w*)\b/i.test(q);
  const origin = /\bwhere do (my |the )?(best|good|top|useful)\b[^?]*\bcome from\b/i.test(q);
  const listOnly = /\bwhat (feeds|sources)\b[^?]*\b(watching|following|follow|have)\b/i.test(q) && !/\b(good|worth|doing|best)\b/i.test(q);
  return !listOnly && ((subject && quality) || origin);
}

// "last 30 days", "this week", "past month" -> a whole number of days; '' = all time.
function scorecardDays(question) {
  const q = String(question || '');
  const n = q.match(/\b(?:last|past)\s+(\d{1,3})\s+days?\b/i);
  if (n) return n[1];
  if (/\b(this|last|past) week\b/i.test(q)) return '7';
  if (/\b(this|last|past) month\b/i.test(q)) return '30';
  return '';
}

function needsFreshLookup({ question, reply, toolsUsed }) {
  const q = String(question || '');
  const r = String(reply || '');
  if (sourceQualityQ(q) && !(toolsUsed || []).includes('manage_sources')) return { retry: true, reason: 'source quality: needs the scorecard' };
  if (Array.isArray(toolsUsed) && toolsUsed.length > 0) return { retry: false, reason: 'tool ran' };
  if (!r.trim()) return { retry: true, reason: 'empty reply' };

  const claimsAction = /\b(running|started|starting|kicked off|launching|searching|scraping)\b[^.?!]*\b(search|sweep|discovery|scrape|run)\b/i.test(r);
  if (claimsAction) return { retry: true, reason: 'claims an action it did not take' };

  // Question-side check (added 2026-10-10, live failure): "anything on bangladesh
  // bank?" got "Nothing scored 7+ from today on Bangladesh Bank yet." with no tool
  // call — wording the reply regex below did not catch. Reply wording is endless;
  // the question is not. A feed question or an item follow-up always needs a tool.
  const aboutSourcesQ = /\b(sources?|feeds?|follow(ing)?|subscri\w*|blogs?|rss|watching)\b/i.test(q);
  const feedQuestion = /\b(anything (on|about|new|good|from)|what about|what('s| is) (new|happening)|tell me (more|about)|more (on|about)|show me|catch me up|what did (you|we) (find|get)|any (news|updates?|items?)|(first|second|third|fourth|fifth|last) one)\b|#\s?\d+\b|\b(number|item|no\.?)\s?\d+\b|^\s*\d+[.)]\s/i.test(q);
  if (feedQuestion && !aboutSourcesQ) return { retry: true, reason: 'feed question answered without a lookup' };

  // Any factual question answered without a tool (added 2026-10-12, end-to-end
  // test of passage search): mid-chat the 9B answered "how long is the context
  // Anthropic adds to each chunk?" with an invented "512 tokens" and no lookup;
  // the reply never mentioned the feed, so the reply check below let it pass.
  // Facts come from the feed (rule 0) until a general-knowledge fallback is
  // designed. Small talk, and questions about sources/runs (answered from the
  // per-message context), are exempt.
  const smallTalk = /\b(how are you|thanks?|thank you|hello|good (morning|night|evening)|who are you|what can you do|what do you do|help me use|how do (i|you) use)\b|^\s*(hi|hey|ok(ay)?|cool|nice|great)\b/i.test(q);
  const aboutRunsQ = /\b(runs?|status|break|broke|broken|fail(ed|ing)?|working|stuck|queue)\b/i.test(q);
  const factQuestion = /\?\s*$|^\s*(who|what|which|when|where|why|how|is|are|was|were|does|do|did|can|could|has|have|should|tell me)\b/i.test(q);
  if (factQuestion && !smallTalk && !aboutSourcesQ && !aboutRunsQ) return { retry: true, reason: 'question answered without a lookup' };

  const claimsFindings = /\b(found|items?|articles?|stor(y|ies)|findings?|coverage|headlines?|i checked|in the feed|the feed (has|shows)|nothing (on|about|new)|no (recent |new |fresh )?(items|news|coverage|results|stories))\b/i.test(r);
  if (!claimsFindings) return { retry: false, reason: 'no feed claims' };

  const aboutSources = /\b(sources?|feeds?|follow(ing)?|subscri\w*|blogs?|rss|watching)\b/i.test(q);
  if (aboutSources) return { retry: false, reason: 'sources come from per-message context' };
  const aboutRuns = /\b(runs?|break|broke|broken|fail(ed|ing)?|work(ed|ing)?|status)\b/i.test(q);
  if (aboutRuns && /\brun\s*#?\d+/i.test(r)) return { retry: false, reason: 'runs come from per-message context' };

  return { retry: true, reason: 'feed claims without a lookup' };
}

// When a reply is rejected, WF-00 runs the lookup ITSELF before the redo and hands
// the result over as live data — the memoryless redo agent was also seen claiming
// "I checked the feed" without a tool (2026-10-10, "anything on the cricket world
// cup?"). Item follow-ups resolve by number; everything else is a topic read on
// the question with its lead-in stripped (WF-31 matches by meaning, so the rest of
// the wording is fine as is).
const ORDINALS = { first: 1, second: 2, third: 3, fourth: 4, fifth: 5, sixth: 6, seventh: 7, eighth: 8, ninth: 9, tenth: 10 };
function prefetchFor(question) {
  const q = String(question || '').trim();
  const ord = q.match(/\b(first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth) (one|item|article|story|link)\b/i);
  if (ord) return { item: String(ORDINALS[ord[1].toLowerCase()]), tag: '' };
  const num = q.match(/#\s?(\d{1,3})\b|\b(?:number|item|no\.?)\s?(\d{1,3})\b|^\s*(\d{1,3})[.)]\s/i);
  if (num) return { item: num[1] || num[2] || num[3], tag: '' };
  const tag = q
    .replace(/^\s*(hey|hi|so|ok(ay)?|and|also)[,!\s]+/i, '')
    .replace(/^\s*(is there |do we have |have you got |got )?(anything|any (news|updates?|items?)|what('s| is)? (new|happening)|what about|tell me (more )?about|more (on|about)|show me|catch me up)\s*(on|about|with|for|regarding)?\s*/i, '')
    .replace(/[?!.]+\s*$/, '')
    .replace(/^the\s+/i, '')
    .trim();
  // 20 words, not 12: whole questions are fine now that WF-31 searches
  // passages by meaning ("how long is the context Anthropic adds to each chunk
  // in contextual retrieval" is 13 words and came back with no prefetch).
  return { item: '', tag: tag.split(/\s+/).length <= 20 ? tag : '' };
}

// Fix 1a (on trial 2026-10-12): every figure and name in a reply must appear
// in what the tools returned this turn. Inlined into WF-00's Guard check and
// Final check.
//
// Why: the 9B fills gaps from memory — "Anthropic adds 512 tokens" (the
// article says 50-100), "Harvey raised $15M in a seed round". Figures are the
// most common invention and the easiest to check: a number either appears in
// the evidence or it does not.
// Limit: a real name in the wrong place passes — "Langfuse was acquired by
// Databricks" names a company that IS in the same article (it bought someone
// else). Catching that needs a model judging each claim, not string matching.

const NAME_STOP = new Set(('I The This That These Those It Its If In On At For From To Of And Or But So As By With Without Yes No Not ' +
  'AI Would Do Does Did Is Are Was Were Be Can Could Should Will Also Here There What Which Who When Where Why How ' +
  'Based According Under Over After Before Since During While Both Each Every Some Any All Most Many More Less Other ' +
  'Feed Item Items Article Articles Source Sources Summary Evidence Passage Note Older Latest Recent New Score ' +
  'Telegram Overseer Exa Tavily Brave RSS Want Shall Let Sure OK Okay Please Thanks Here ' +
  // dates get reworded ("January" for "Jan"); they are not names
  'January February March April May June July August September October November December ' +
  'Jan Feb Mar Apr Jun Jul Aug Sep Sept Oct Nov Dec Monday Tuesday Wednesday Thursday Friday Saturday Sunday').split(' ').map((w) => w.toLowerCase()));

// Same spelling for "$1.2 billion" / "$1.2B" / "1,200" / "40–60 percent".
// Evidence often arrives as JSON text, where a line break is the two
// characters \n: "$581.7\n\nbillion" in a PDF report did not match "$581.7B"
// in the matrix runs (2026-10-12), so escapes and runs of whitespace go first.
function norm(s) {
  return String(s || '').toLowerCase()
    .replace(/\\[nrt]/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/[‐-―−]/g, '-')
    .replace(/(\d),(?=\d{3}\b)/g, '$1')
    .replace(/\$\s?/g, '')
    .replace(/(\d)\s?(billion|bn)\b/g, '$1b')
    .replace(/(\d)\s?(million|mn)\b/g, '$1m')
    .replace(/(\d)\s?(thousand)\b/g, '$1k')
    .replace(/(\d)\s?(percent|per cent)\b/g, '$1%')
    .replace(/(\d)\s+(%|b|m|k)\b/g, '$1$2')
    // amounts as full numbers: "$400K" and "$400,000" (a matrix false alarm) both become 400000
    .replace(/(\d+(?:\.\d+)?)(k|m|b)\b/g, (x, n, u) => String(Math.round(Number(n) * { k: 1e3, m: 1e6, b: 1e9 }[u])));
}

const esc = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Figures: numbers with an optional unit. Skipped: small bare counts (list
// numbers, item n), years, and anything the question itself contains.
function figures(text, question) {
  const q = norm(question);
  const out = new Set();
  for (const m of norm(text).matchAll(/(?<![\w.])(\d+(?:\.\d+)?)(%|b|m|k|x)?(?![\w])/g)) {
    const num = Number(m[1]), tok = m[1] + (m[2] || '');
    if (!m[2] && num <= 20 && !m[1].includes('.')) continue;
    if (!m[2] && num >= 1990 && num <= 2035 && !m[1].includes('.')) continue;
    if (new RegExp('(?<![\\d.])' + esc(tok) + '(?![\\d])').test(q)) continue;
    out.add(tok);
  }
  return [...out];
}

// Names: capitalised words that do not start a sentence or a list line.
function names(text, question) {
  const q = norm(question);
  const out = new Set();
  const t = String(text || '').replace(/\*\*|__|`/g, '');
  for (const m of t.matchAll(/(?<=[a-z0-9,;:()"'’] )([A-Z][A-Za-z0-9&-]*[A-Za-z0-9](?: [A-Z][A-Za-z0-9&-]*[A-Za-z0-9])*)/g)) {
    const words = m[1].split(' ').filter((w) => !NAME_STOP.has(w.toLowerCase()) && w.length > 1);
    if (!words.length) continue;
    const name = words.join(' ');
    if (q.includes(name.toLowerCase())) continue;
    out.add(name);
  }
  return [...out];
}

// What in the reply is not in the evidence. A figure must appear as written
// (after norm). Names are opt-in: in the matrix runs (2026-10-12) the name
// check raised only false alarms — bullet headings ("Levers", "Thresholds"),
// "Liberation Army" for "People's Liberation Army" — and replaced one good
// answer, while the invention it was meant for ("Databricks") passes anyway.
function unsupportedFacts(reply, evidence, question, opts) {
  const ev = norm(evidence);
  const missing = [];
  for (const f of figures(reply, question)) {
    if (!new RegExp('(?<![\\d.])' + esc(f) + '(?![\\d])').test(ev)) missing.push(f);
  }
  if (opts && opts.names) {
    for (const n of names(reply, question)) {
      if (!n.toLowerCase().split(' ').some((w) => ev.includes(w))) missing.push(n);
    }
  }
  return missing;
}

// #14 long-term memory (2026-10-13): the bot sees only its last 10 exchanges, so
// every finished exchange is also kept in chat_memory (sql/016) and searched by
// meaning before the agent runs. Inlined into WF-00 ('Recall sql', 'Recall note',
// 'Remember prep', 'Remember sql') together with embed.js.
//
// Measured on his 33 real exchanges, 19 recall questions + 14 never discussed
// (scripts/eval-recall.js):
//  - one "You: ... / Bot: ..." text per exchange beats the question alone: right
//    exchange on top 18/19 vs 16/19;
//  - cutoff 0.50: 17/19 found, 13/14 never-discussed left empty. The one false
//    recall ("openai funding" -> his "AI agent funding" exchange, 0.59) scores
//    above real hits, so no cutoff removes it; a 9B relevance check gave no gain
//    (17/19, 13/14) and cost 0.26 s per exchange, so recalled exchanges carry
//    their date and question and a wrong one is visible instead;
//  - typos need no fixing here: "husssain elius" found its exchange at 0.59,
//    the next best 0.21.

const RECALL_CUTOFF = 0.50;
const RECALL_LIMIT = 3;
const RECALL_ANSWER_CHARS = 1200;

// What gets embedded and stored: the exchange as he saw it.
function memoryDoc(question, answer) {
  return ('You: ' + String(question || '').trim() + '\nBot: ' + String(answer || '').trim()).slice(0, 2000);
}

// Not worth keeping: taps, empty or failed replies.
function shouldRemember(question, answer) {
  const q = String(question || '').trim(), a = String(answer || '').trim();
  if (!q || !a) return false;
  if (q.startsWith('cb:')) return false;
  if (a === '(empty reply)') return false;
  return true;
}

const b64 = (s) => Buffer.from(String(s == null ? '' : s).replace(/\u0000/g, ''), 'utf8').toString('base64');

// Web text goes in base64: n8n's Postgres node reads some $-digit runs as
// parameters even inside quotes (CLAUDE.md). vec = vectorLiteral output (numbers only).
function rememberSql(chatId, question, answer, vec) {
  const id = String(chatId == null ? '' : chatId).trim();
  if (!/^-?\d+$/.test(id)) return 'select 1 as skipped';
  return "insert into chat_memory (chat_id, question, answer, embedding) values (" + id +
    ", convert_from(decode('" + b64(question) + "', 'base64'), 'UTF8'), convert_from(decode('" + b64(answer) +
    "', 'base64'), 'UTF8'), " + (vec ? "'" + vec + "'::vector" : 'null') + ') returning id';
}

// One row back (the SQL runner and n8n both like that): rows = json array or null.
function recallSql(chatId, vec, cutoff = RECALL_CUTOFF, limit = RECALL_LIMIT) {
  const id = String(chatId == null ? '' : chatId).trim();
  if (!/^-?\d+$/.test(id) || !vec) return 'select null::text as rows';
  return "select (select json_agg(r order by r.sim desc)::text from (select id, question, answer, " +
    "to_char(created_at at time zone 'Asia/Dhaka', 'FMDD Mon') as day, 1 - (embedding <=> '" + vec + "'::vector) as sim " +
    'from chat_memory where chat_id = ' + id + " and embedding is not null order by embedding <=> '" + vec + "'::vector limit " +
    Number(limit) + ') r where r.sim >= ' + Number(cutoff) + ') as rows';
}

function parseRows(rows) {
  if (Array.isArray(rows)) return rows;
  try { const v = JSON.parse(String(rows || 'null')); return Array.isArray(v) ? v : []; } catch (e) { return []; }
}

// What the agent is handed. It rides after the [live data ...] marker, so Tidy
// memory strips it from the stored message like the rest of the live data.
// A question about what was said before, with nothing recalled: the 9B mirrored
// "what did we discuss about nvidia earnings?" with "We discussed NVIDIA earnings
// in this chat" and then listed feed items (end to end, 2026-10-13).
const ASKS_HISTORY = /\b(we (discuss|discussed|talk|talked|spoke)|you (told|tell|said|say|found|gave|showed|mentioned)|did (i|we) (ask|discuss|talk)|i asked( you)?|remind me what|last time)\b/i;
const NO_HISTORY = '[earlier chats with this user: none match this message. If they ask what was said before, say plainly you have no record of discussing it, then answer from the feed if it helps.]';

function recallNote(rows, question) {
  const list = parseRows(rows);
  if (!list.length) return ASKS_HISTORY.test(String(question || '')) ? NO_HISTORY : '';
  const lines = list.map((r) => '(' + (r.day || 'earlier') + ') You: ' + String(r.question || '').replace(/\s+/g, ' ').slice(0, 300) +
    ' | Bot: ' + String(r.answer || '').replace(/\s+/g, ' ').slice(0, RECALL_ANSWER_CHARS));
  return '[earlier chats with this user, found by meaning, may be unrelated: ' + lines.join(' || ') +
    ' ] [Use an earlier chat only if it is about what this message asks. When you use one, say when: "On 13 Oct I told you ..." or "Earlier you asked ...". It is what was said then, not the feed.]';
}

// The guard (answer-guard.js) redoes a factual answer given without a tool. An
// answer built on a recalled exchange says so ("On 13 Oct ...", "earlier"), and
// only then does the recall count as the lookup.
const USES_RECALL = /\b(earlier|previously|before|last time|you asked|i (told|found|said|gave)|we (talked|discussed|spoke))\b|\bon \d{1,2} (jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)\w*\b/i;
function usesRecall(reply, recallN) {
  return Number(recallN) > 0 && USES_RECALL.test(String(reply || ''));
}

// The web fallback's wording rule (web-fallback.js) must not decide alone on an
// answer built on an earlier chat: end to end, "who founded Pathao again?" got
// "On 13 Oct I told you ... Hussain Elius co-founded Pathao ... Your feed doesn't
// have this topic", and "feed doesn't" sent a right answer to the web (2026-10-13).
// When this is true WF-00 asks the 9B judge instead (a reply that only repeats
// "nothing found" still goes to the web). Only a recalled exchange that itself
// answered counts (wasNoAnswer = web-fallback's verdict on the old reply).
function answeredFromRecall(reply, rows, wasNoAnswer) {
  const list = parseRows(rows);
  if (!usesRecall(reply, list.length)) return false;
  return list.some((r) => /^\s*From the web\b/i.test(String(r.answer || '')) || !wasNoAnswer(r));
}

// A bare short reply ("yes", "ok", "no") is never redone by the answer guard
// (2026-10-17). The redo's Prefetch searched the feed for "yes", got 10
// unrelated items, and the 9B presented them as an answer. A bare reply has no
// topic to look up, so when the guard would redo it the bot asks instead.
// (A "yes" to the sweep question never gets here: shared/sweep-confirm.js.)

const BARE = /^(yes|y|yeah|yep|yup|yea|sure|ok|okay|k|no|n|nope|nah|maybe|go ahead|do it|please|thanks|thank you|thx|cool|great|nice|right|fine|alright|got it)$/i;

function bareReply(text) {
  const t = String(text || '').trim().toLowerCase().replace(/[\s!.?,👍🙏]+$/u, '').replace(/^[\s!.?,]+/, '');
  return t.length <= 20 && BARE.test(t);
}

function bareReplyText(text) {
  const t = String(text || '').trim().toLowerCase();
  if (/^(no|n|nope|nah)\b/.test(t)) return 'OK. What would you like instead? Tell me a topic, a link or a question.';
  if (/^(thanks|thank you|thx|cool|great|nice|got it)\b/.test(t)) return 'Anytime.';
  return 'Yes to what? I have nothing pending for you. Tell me a topic, a link or a question.';
}

const a = $input.first().json;
const ctx = $('Agent input').first().json;
const question = ctx.text || '';
// #14: an answer built on a recalled exchange says so ("On 13 Oct I told you"),
// and only then does the recall count as the lookup (shared/recall.js usesRecall).
let rc = {};
try { rc = $('Recall note').first().json || {}; } catch (e) {}
const recall_note = rc.recall_note || '';
const toolsUsed = (a.intermediateSteps || []).map(s => (s.action && s.action.tool) || '').filter(Boolean);
if (usesRecall(a.output, rc.recall_n)) toolsUsed.push('recall');
let g = needsFreshLookup({ question, reply: a.output, toolsUsed });
// Fix 1a (switch fix_answer_check): figures and names must be in what the tools returned.
if (!g.retry && ctx.fix_check === 'true' && toolsUsed.length) {
  const evidence = (a.intermediateSteps || []).map(s => typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation || '')).join(' ') + ' ' + ctx.sources + ' ' + ctx.runs + ' ' + recall_note;
  const miss = unsupportedFacts(a.output || '', evidence, question);
  if (miss.length) g = { retry: true, reason: 'unsupported: ' + miss.slice(0, 6).join(', ') };
}
// a bare "yes"/"ok" has no topic: a redo would prefetch the feed for "yes" (shared/bare-reply.js)
let output = a.output || '';
if (g.retry && bareReply(question)) { output = bareReplyText(question); g = { retry: false, reason: 'bare reply: asked what it refers to' }; }
const pf = prefetchFor(question);
const sq = String(g.reason || '').startsWith('source quality');
return [{ json: { output, retry: String(g.retry), guard_reason: g.reason, tools_used: toolsUsed.join(','), prefetch_item: pf.item, prefetch_tag: pf.tag,
  source_q: String(sq), scorecard_days: scorecardDays(question), recall_note } }];

